import { readFileSync } from "node:fs";
import { afterEach, describe, expect, it, vi } from "vitest";
import { createSecMsGecGenerator, generateSecMsGecV2 } from "../token.js";

interface Golden {
  source: string;
  secMsGecVersion: string;
  vectors: { unixSeconds: number; token: string }[];
}

// Generated by scripts/gen-token-vectors.py with Python edge-tts 7.3.1.
// Byte-for-byte equality is the contract: one wrong bit and the endpoint answers 403.
const golden = JSON.parse(
  readFileSync(new URL("./token-vectors.json", import.meta.url), "utf8"),
) as Golden;

describe("Sec-MS-GEC v2 token", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("matches edge-tts 7.3.1 golden vectors", () => {
    expect(golden.source).toBe("edge-tts 7.3.1");
    expect(golden.vectors.length).toBeGreaterThanOrEqual(5);
    for (const { unixSeconds, token } of golden.vectors) {
      expect(generateSecMsGecV2(unixSeconds)).toBe(token);
    }
  });

  it("computes without Web Crypto", () => {
    vi.stubGlobal("crypto", undefined);
    expect(globalThis.crypto?.subtle).toBeUndefined();
    const [first] = golden.vectors;
    if (!first) throw new Error("no vectors");
    expect(generateSecMsGecV2(first.unixSeconds)).toBe(first.token);
  });

  it("applies the clock offset", () => {
    const now = 1_791_590_400;
    const offset = 600;
    const token = createSecMsGecGenerator(() => now, offset)();
    expect(token).toBe(generateSecMsGecV2(now + offset));
    expect(token).not.toBe(generateSecMsGecV2(now));
  });
});
